import subprocess,json,time,re
label='gui/501/org.heptabao.qa.mac-authbus-4e808-home-r2.server'
started=time.monotonic()
try:
 p=subprocess.run(['/bin/launchctl','print',label],capture_output=True,timeout=8)
 data=p.stdout.decode('utf-8','strict')
 fields={}
 allowed={'state','pid','runs','last exit code','last terminating signal','active count','execution context'}
 for line in data.splitlines():
  if not line.startswith('\t') or line.startswith('\t\t'): continue
  m=re.fullmatch(r'\t([^=]+?) = (.{0,128})',line)
  if m and m.group(1) in allowed:
   key=m.group(1)
   if key in fields: raise ValueError('duplicate_selected_field')
   fields[key]=m.group(2)
 print(json.dumps({'schema':'heptabao.launchctl-safe-state.v1','target':label,'returncode':p.returncode,'stdout_bytes':len(p.stdout),'stderr_bytes':len(p.stderr),'fields':fields,'source_header_matches':data.startswith(label+' = {'),'elapsed_seconds':time.monotonic()-started,'raw_argv_environment_or_stderr_exported':False,'service_mutation':False}))
except Exception as e:
 print(json.dumps({'schema':'heptabao.launchctl-safe-state.v1','target':label,'error_type':type(e).__name__,'elapsed_seconds':time.monotonic()-started,'service_mutation':False}))
 raise SystemExit(1)
